org.jenkinsci.plugins.pipeline.modeldefi.value:
withVault(
                        configuration: [
                            vaultUrl: 'http://127.0.0.1:8200',
                            vaultCredentialId: 'vault-token',
                            engineVersion: 2
                        ],
                        vaultSecrets: [[
                            path: 'secret/jenkins',
                            secretValues: [
                                [
                                    envVar: 'DB_USERNAME',
                                    vaultKey: 'username'
                                ],
                                [
                                    envVar: 'DB_PASSWORD',
                                    vaultKey: 'password'
                                ]
                            ]
                        ]]
                    ) {
                        sh '''
                            echo "Vault secret retrieval successful"
                            test -n "$DB_USERNAME"
                            test -n "$DB_PASSWORD"
                        '''
                    }

execution.script:
pipeline {
    agent any

    stages {
        stage('Retrieve Vault Secret') {
            steps {
                script {
                    withVault(
                        configuration: [
                            vaultUrl: 'http://127.0.0.1:8200',
                            vaultCredentialId: 'vault-token',
                            engineVersion: 2
                        ],
                        vaultSecrets: [[
                            path: 'secret/jenkins',
                            secretValues: [
                                [
                                    envVar: 'DB_USERNAME',
                                    vaultKey: 'username'
                                ],
                                [
                                    envVar: 'DB_PASSWORD',
                                    vaultKey: 'password'
                                ]
                            ]
                        ]]
                    ) {
                        sh '''
                            echo "Vault secret retrieval successful"
                            test -n "$DB_USERNAME"
                            test -n "$DB_PASSWORD"
                        '''
                    }
                }
            }
        }
    }
}
